def all_subsets(nums: list[int]) -> list[list[int]]:
    res, path = [], []

    def bt(start: int) -> None:
        res.append(path[:])
        for i in range(start, len(nums)):
            path.append(nums[i])
            bt(i + 1)
            path.pop()

    bt(0)
    return res
